using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class PolishTown170 {public static string Main(){const string D="Assets/Events/NewYear/WinterTown170/";int wallVerts=0,stackParts=0,snowParts=0;
foreach(var guid in AssetDatabase.FindAssets("t:Mesh",new[]{D.TrimEnd('/')})){var path=AssetDatabase.GUIDToAssetPath(guid);var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!m.name.StartsWith("Inner_Wall_Decor"))continue;var vs=m.vertices;for(int i=0;i<vs.Length;i++){var p=vs[i];if(Mathf.Abs(p.x)>55)p.x-=Mathf.Sign(p.x)*7.3f;else if(p.z>51)p.z-=p.x>0?2.55f:3.2f;else if(p.z< -51&&p.x<0)p.z-=.55f;vs[i]=p;wallVerts++;}m.vertices=vs;m.RecalculateBounds();EditorUtility.SetDirty(m);}
var giftMeshes=AssetDatabase.FindAssets("t:Mesh",new[]{D.TrimEnd('/')}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Mesh>).Where(m=>m.name.StartsWith("Colorful_Presents")).ToArray();var boxes=new List<Bounds>();foreach(var m in giftMeshes){var vs=m.vertices;if(vs.Length%24!=0)throw new Exception("Unexpected cube vertex layout");for(int i=0;i<vs.Length;i+=24){var b=new Bounds(vs[i],Vector3.zero);for(int j=1;j<24;j++)b.Encapsulate(vs[i+j]);if(Mathf.Abs(b.size.x-b.size.z)<.01f&&Mathf.Abs(b.size.y-.8f*b.size.x)<.01f&&b.min.y<.2f)boxes.Add(b);}}
foreach(var m in giftMeshes){var vs=m.vertices;for(int i=0;i<vs.Length;i+=24){var b=new Bounds(vs[i],Vector3.zero);for(int j=1;j<24;j++)b.Encapsulate(vs[i+j]);if(b.min.y<1.3f)continue;var bases=boxes.Where(bb=>Mathf.Abs(bb.center.x-b.center.x)<.02f&&Mathf.Abs(bb.center.z-b.center.z)<.02f).ToArray();if(bases.Length!=1)throw new Exception("Missing support under stacked gift "+b.center);float shift=bases[0].max.y-1.37f;for(int j=0;j<24;j++)vs[i+j]+=Vector3.up*shift;stackParts++;}m.vertices=vs;m.RecalculateBounds();EditorUtility.SetDirty(m);}
var sm=AssetDatabase.LoadAssetAtPath<Mesh>(D+"Rounded_Snowdrifts_Snow.asset");var sv=sm.vertices;if(sv.Length%46!=0)throw new Exception("Unexpected snow layout");int n=sv.Length/46;for(int i=0;i<sv.Length;i+=n){var b=new Bounds(sv[i],Vector3.zero);for(int j=1;j<n;j++)b.Encapsulate(sv[i+j]);if(Mathf.Abs(b.center.x)<46)continue;for(int j=0;j<n;j++){var p=sv[i+j];p.x=Mathf.Sign(b.center.x)*47.2f+(p.x-b.center.x)*5.8f/b.size.x;sv[i+j]=p;}snowParts++;}sm.vertices=sv;sm.RecalculateNormals();sm.RecalculateBounds();EditorUtility.SetDirty(sm);AssetDatabase.SaveAssets();return "Wall vertices fitted="+wallVerts+"; stacked gift parts supported="+stackParts+"; rear snowbanks kept inside walls="+snowParts;}}